const config=window.FULLTANK_CONFIG||{};
const slider=document.querySelector('#litros');
function calculate(){const liters=Number(slider.value);document.querySelector('#litrosValor').textContent=liters;document.querySelector('#economia').textContent=(liters*.1).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});document.querySelector('.result small').textContent=`${liters} L × R$ 0,10 por litro`;}
slider.addEventListener('input',calculate);calculate();
const modal=document.querySelector('#notice');
function notice(title,text){document.querySelector('#noticeTitle').textContent=title;document.querySelector('#noticeText').textContent=text;modal.showModal();}
document.querySelectorAll('.close,.close-action').forEach(b=>b.addEventListener('click',()=>modal.close()));
function safeUrl(value){try{const url=new URL(value);return url.protocol==='https:'?url.href:null;}catch{return null;}}
document.querySelectorAll('[data-store]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.store==='ios'?'iosUrl':'androidUrl';const url=safeUrl(config[key]);if(url){window.open(url,'_blank','noopener,noreferrer');}else notice('Download do Fulltank+','Os links oficiais das lojas estão sendo preparados para esta página. Nenhum download foi iniciado.');}));
document.querySelector('#leadForm').addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));const phone=data.telefone.replace(/\D/g,'');if(phone.length<10||phone.length>13){document.querySelector('#formStatus').textContent='Confira seu WhatsApp com DDD.';return;}const message=`Olá! Quero conhecer o Fulltank+ para meu posto.\nNome: ${data.nome}\nWhatsApp: ${data.telefone}\nPosto/rede: ${data.posto}\nCidade: ${data.cidade}\nUnidades: ${data.unidades}`;const destination=String(config.salesWhatsapp||'').replace(/\D/g,'');if(destination.length>=12&&destination.length<=15){window.open(`https://wa.me/${destination}?text=${encodeURIComponent(message)}`,'_blank','noopener,noreferrer');document.querySelector('#formStatus').textContent='Continue no WhatsApp para enviar sua solicitação. O formulário não envia dados automaticamente.';}else{notice('Contato comercial em preparação','Esta é uma prévia. O canal comercial ainda não foi configurado e seus dados não foram enviados nem armazenados.');document.querySelector('#formStatus').textContent='Nenhum dado enviado. Canal comercial pendente de configuração.';}});
document.querySelector('#year').textContent=new Date().getFullYear();
